using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using ReelBolt.Inference.Api.Data;
using ReelBolt.Inference.Api.Services.Auth;
using ReelBolt.Inference.Api.Services.Outputs;
using ReelBolt.Shared.Auth;
using ReelBolt.Shared.Data.Models;
using ReelBolt.Shared.Storage;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace ReelBolt.Inference.Api.Controllers;

/// <summary>
/// Provides access to project timeline metadata and artifacts generated by workflow steps.
/// </summary>
[ApiController]
[Route("api/v1/projects/{projectId:guid}/timelines")]
[Authorize]
public class TimelinesController : ControllerBase
{
    private readonly InferenceApiDbContext _db;
    private readonly ICurrentUser _currentUser;
    private readonly IProjectAccessService _projectAccess;

    public TimelinesController(
        InferenceApiDbContext db,
        ICurrentUser currentUser,
        IProjectAccessService projectAccess)
    {
        _db = db;
        _currentUser = currentUser;
        _projectAccess = projectAccess;
    }

    /// <summary>
    /// Lists all workflow step results in this project that have a generated timeline artifact
    /// or compiled video with a timeline, ordered most recent first.
    /// </summary>
    [HttpGet]
    public async Task<ActionResult<List<ProjectTimelineResponse>>> ListTimelines(Guid projectId, CancellationToken ct)
    {
        ProjectAccessResult access = await _projectAccess.GetAsync(projectId, ProjectPermission.View, ct);
        if (access.Failure is { } denied) return denied;
        Project project = access.Project!;

        // Single indexed query: TimelineStorageKey != null && ProjectId == projectId
        List<WorkflowStepResult> stepResults = await _db.WorkflowStepResults
            .Where(r => r.TimelineStorageKey != null)
            .Include(r => r.WorkflowExecution)
            .Where(r => r.WorkflowExecution.ProjectId == projectId)
            .OrderByDescending(r => r.CompletedAt ?? r.ExecutedAt)
            .ToListAsync(ct);
        // A result whose output is not served is left out of the list like a missing one.
        HashSet<Guid> unavailable = await OutputGate.HeldResultIdsAsync(_db, projectId, stepResults.Select(r => r.Id).ToList(), ct);
        if (unavailable.Count > 0) stepResults = stepResults.Where(r => !unavailable.Contains(r.Id)).ToList();

        // Final-deliverable marking: same rule and same candidate set as the outputs list (renders under
        // outputFiles/ or agentFiles/generated/, not copied from an earlier run), over the runs listed here.
        List<Guid> executionIds = stepResults.Select(r => r.WorkflowExecutionId).Distinct().ToList();
        string outputPrefix = ProjectOutputKeys.OutputFilesPrefix(projectId);
        string generatedPrefix = ProjectOutputKeys.GeneratedPrefix(projectId);
        var renderRows = await _db.WorkflowStepResults
            .Where(r => executionIds.Contains(r.WorkflowExecutionId)
                && r.OutputStorageKey != null
                && r.ReusedFromStepResultId == null
                && (r.OutputStorageKey.StartsWith(outputPrefix) || r.OutputStorageKey.StartsWith(generatedPrefix)))
            .OrderByDescending(r => r.CompletedAt ?? r.ExecutedAt)
            .Select(r => new RenderCandidate(r.Id, r.WorkflowExecutionId, r.Status, r.CompletedAt ?? r.ExecutedAt))
            .ToListAsync(ct);
        var executions = await _db.WorkflowExecutions
            .Where(e => executionIds.Contains(e.Id))
            .Select(e => new { e.Id, e.WorkflowDefinitionId, e.Status })
            .ToDictionaryAsync(e => e.Id, ct);
        HashSet<Guid> finalRenderIds = FinalRenders.FinalRenderIds(
            renderRows, id => executions.TryGetValue(id, out var e) && e.Status == ExecutionStatus.Passed);
        List<Guid> workflowIds = executions.Values.Select(e => e.WorkflowDefinitionId).Distinct().ToList();
        Dictionary<Guid, string> workflowNames = await _db.WorkflowDefinitions
            .Where(w => workflowIds.Contains(w.Id))
            .ToDictionaryAsync(w => w.Id, w => w.Name, ct);
        List<Guid> stepIds = stepResults.Select(r => r.WorkflowStepId).Distinct().ToList();
        Dictionary<Guid, string> stepLabels = await _db.WorkflowSteps
            .Where(s => stepIds.Contains(s.Id))
            .ToDictionaryAsync(s => s.Id, s => s.Label, ct);
        // "Run 3" = third execution of that workflow by start time (same ordinal as the outputs list).
        var siblingRuns = await _db.WorkflowExecutions
            .Where(e => e.ProjectId == projectId && workflowIds.Contains(e.WorkflowDefinitionId))
            .Select(e => new { e.Id, e.WorkflowDefinitionId, e.StartedAt })
            .ToListAsync(ct);
        Dictionary<Guid, int> runNumbers = siblingRuns
            .GroupBy(e => e.WorkflowDefinitionId)
            .SelectMany(g => g
                .OrderBy(e => e.StartedAt ?? DateTime.MaxValue)
                .ThenBy(e => e.Id)
                .Select((e, i) => (e.Id, Number: i + 1)))
            .ToDictionary(x => x.Id, x => x.Number);
        var responses = new List<ProjectTimelineResponse>(stepResults.Count);
        foreach (WorkflowStepResult r in stepResults)
        {
            JsonObject? outputObj = null;
            if (!string.IsNullOrWhiteSpace(r.OutputJson))
            {
                try
                {
                    JsonNode? parsed = JsonNode.Parse(r.OutputJson);
                    outputObj = parsed as JsonObject;
                }
                catch (JsonException) { }
            }

            string? outputVideoStorageKey = r.OutputStorageKey;
            if (string.IsNullOrEmpty(outputVideoStorageKey) && outputObj != null && outputObj.TryGetPropertyValue("outputStorageKey", out JsonNode? outKeyNode))
            {
                outputVideoStorageKey = TryGetString(outKeyNode);
            }

            double? durationSec = ExtractDuration(outputObj);

            string? explicitFileName = null;
            if (outputObj != null && outputObj.TryGetPropertyValue("fileName", out JsonNode? fnNode))
            {
                explicitFileName = TryGetString(fnNode);
            }

            string fileName = !string.IsNullOrWhiteSpace(explicitFileName)
                ? explicitFileName
                : (!string.IsNullOrEmpty(outputVideoStorageKey)
                    ? Path.GetFileName(outputVideoStorageKey)
                    : (!string.IsNullOrEmpty(r.TimelineStorageKey)
                        ? Path.GetFileName(r.TimelineStorageKey)
                        : "timeline.json"));

            responses.Add(new ProjectTimelineResponse(
                r.Id,
                r.WorkflowExecutionId,
                r.WorkflowStepId,
                r.TimelineStorageKey,
                outputVideoStorageKey,
                fileName,
                durationSec,
                r.CompletedAt ?? r.ExecutedAt,
                finalRenderIds.Contains(r.Id),
                executions.TryGetValue(r.WorkflowExecutionId, out var ex) && workflowNames.TryGetValue(ex.WorkflowDefinitionId, out string? wfName) ? wfName : null,
                runNumbers.TryGetValue(r.WorkflowExecutionId, out int run) ? run : null,
                stepLabels.TryGetValue(r.WorkflowStepId, out string? label) ? label : null));
        }

        return Ok(responses);
    }

    private static string? TryGetString(JsonNode? node) => node is JsonValue v &&
        v.TryGetValue(out string? s) ? s : null;

    private static double? ExtractDuration(JsonObject? obj)
    {
        if (obj == null) return null;
        JsonNode? durationNode = null;
        if (!obj.TryGetPropertyValue("outputDurationSec", out durationNode) &&
            !obj.TryGetPropertyValue("durationSec", out durationNode))
        {
            obj.TryGetPropertyValue("duration", out durationNode);
        }
        if (durationNode == null) return null;

        if (durationNode is JsonValue val)
        {
            if (val.TryGetValue<double>(out double d))
                return d;
            string? s = TryGetString(durationNode);
            if (s != null &&
                double.TryParse(s, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double parsed))
            {
                return parsed;
            }
        }
        return null;
    }
}

public record ProjectTimelineResponse(
    Guid StepResultId,
    Guid WorkflowExecutionId,
    Guid WorkflowStepId,
    string? TimelineStorageKey,
    string? OutputVideoStorageKey,
    string FileName,
    double? DurationSec,
    DateTime CreatedAt,
    bool IsFinal = false,
    string? WorkflowName = null,
    int? RunNumber = null,
    string? StepLabel = null);
